/** Press *key* on item *current*, or -- with focus on no item (`-1`) -- on the panel while the control holds focus. */
function press(section: HTMLElement, current: number, key: string): void {
  const items = Array.from(section.querySelectorAll<HTMLElement>('[role="menuitem"]'));
  let target: HTMLElement | null;
  if (current >= 0) {
    items[current].focus();
    target = items[current];
  } else {
    section.querySelector<HTMLElement>('#trigger')?.focus();
    target = section.querySelector<HTMLElement>('[role="menu"]');
  }
  target?.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true }));
}

